def program_acc(p, cases, ablated):
    if not cases:
        return 0.0
    return sum((p.execute(e['input'], ablated=ablated) == e['expected'] for e in cases)) / len(cases)

def program_acc(p, cases, ablated):
    if not cases:
        return 0.0
    return sum((BoundedRuleSandbox.execute(p, e['input'], ablated=ablated) == e['expected'] for e in cases)) / len(cases)

def predict(tree, row):
    cur = tree
    while 'label' not in cur:
        cur = cur['true'] if bool(row.get(cur['feature'])) else cur['false']
    return cur['label']

def active(ctx):
    out = []
    if ctx['current_generation_active']:
        out.extend(GEN)
    if not ctx['lineage_verified']:
        out.append(CAN[0])
    if not ctx['dependency_lock_verified']:
        out.append(CAN[1])
    if not ctx['evidence_fetch_hardened']:
        out.append(CAN[2])
    if not ctx['historical_state_protected']:
        out.append(CAN[3])
    out.extend(CAN[4:])
    return out

def _segments(text):
    parts = [p.strip() for p in re.split('(?<=[.!?;:])\\s+', str(text)) if p.strip()]
    return parts or [str(text).strip()]

def effective(ctx, ablated):
    out = []
    for role in ALL:
        payload = {'role': role, **ctx, 'irrelevant_nonce': 99}
        if BoundedRuleSandbox.execute(dev_p_obj, payload, ablated=ablated) == 'KEEP':
            out.append(role)
    return out

def eval_rule(rule, manifest_frontier, head_frontier, open_deficits):
    if rule == 'NONEMPTY':
        return isinstance(manifest_frontier, str) and bool(manifest_frontier)
    if rule == 'HEAD_MANIFEST_CONSISTENT':
        return bool(manifest_frontier) and manifest_frontier == head_frontier
    if rule == 'HEAD_MANIFEST_CONSISTENT_WITH_LEDGER':
        return bool(manifest_frontier) and manifest_frontier == head_frontier and isinstance(open_deficits, list) and (len(open_deficits) >= 1)
    if rule == 'EXACT_OLD':
        return manifest_frontier == 'G2_RAW_TASK_REPRESENTATION_AND_GROUNDING_V1'
    raise ValueError(rule)

def wrapper_signal(text):
    t = str(text)
    if re.search('\\[[^\\]]{0,160}\\]', t):
        return True
    seg = _segments(t)
    return len(seg) >= 2 and (len(_tokens(seg[0])) <= 4 or len(_tokens(seg[-1])) <= 4)

def ensure_support(gen, start):
    out = []
    for i in range(4):
        out.extend(gen(start + i, 80))
    return out

def core_view(text):
    t = edge_delimiterless(text)
    seg = _segments(t)
    if len(seg) >= 2 and len(_tokens(seg[0])) <= 4:
        seg = seg[1:]
    if len(seg) >= 2 and len(_tokens(seg[-1])) <= 4:
        seg = seg[:-1]
    out = ' '.join(seg).strip()
    return out or t

def dev_cases(ctxs, noise_seed):
    r = random.Random(noise_seed)
    out = []
    for c in ctxs:
        for role in ALL:
            x = {'role': role, **c, 'irrelevant_nonce': r.randint(0, 3)}
            out.append({'input': x, 'expected': 'KEEP' if role in active(c) else 'DROP'})
    return out

def transfer_a_cases(seed, n):
    r = random.Random(seed)
    out = []
    for _ in range(n):
        x = {'source_kind': r.choice(['REAL', 'SIMULATED', 'DERIVED']), 'verified': r.choice([True, False]), 'priority': r.choice(['LOW', 'HIGH']), 'noise': r.randint(0, 5)}
        y = 'WITHHOLD' if x['source_kind'] == 'SIMULATED' and (not x['verified']) else 'ACCEPT'
        out.append({'input': x, 'expected': y})
    return out

def transfer_b_cases(seed, n):
    r = random.Random(seed)
    out = []
    for _ in range(n):
        x = {'component': r.choice(['CORE', 'PLUGIN', 'EXPERIMENT']), 'tests_passed': r.choice([True, False]), 'rollback_ready': r.choice([True, False]), 'noise': r.randint(0, 5)}
        y = 'PROMOTE' if x['component'] == 'EXPERIMENT' and x['tests_passed'] and x['rollback_ready'] else 'HOLD'
        out.append({'input': x, 'expected': y})
    return out

def discover_pivot_candidates(rows, max_candidates, min_df):
    df = Counter()
    for text, _ in rows:
        for w in set(words(text)):
            df[w] += 1
    ranked = sorted([(n, w) for w, n in df.items() if n >= min_df and len(w) >= 2], key=lambda z: (-z[0], z[1]))
    return [w for _, w in ranked[:max_candidates]]

def features(text, mode, dim, pivot):
    c = Counter()
    _add_ngram(c, 'F|', text, dim, 1.0)
    ws = words(text)
    if mode in ('POSITIONAL', 'CLAUSE', 'PIVOT_CLAUSE'):
        q = max(1, (len(ws) + 3) // 4)
        for i in range(4):
            seg = ' '.join(ws[i * q:(i + 1) * q])
            if seg:
                _add_ngram(c, f'P{i}|', seg, dim, 0.65)
    if mode in ('CLAUSE', 'PIVOT_CLAUSE'):
        cs = clauses(text)
        for i, seg in enumerate(cs):
            tag = 'LAST' if i == len(cs) - 1 else 'FIRST' if i == 0 else 'MID'
            _add_ngram(c, tag + '|', seg, dim, 0.8 if tag == 'LAST' else 0.55)
    if mode == 'PIVOT_CLAUSE' and pivot:
        idx = [i for i, w in enumerate(ws) if w == pivot]
        if idx:
            j = idx[-1]
            pre = ' '.join(ws[:j])
            post = ' '.join(ws[j + 1:])
            if pre:
                _add_ngram(c, 'PRE|', pre, dim, 0.45)
            if post:
                _add_ngram(c, 'POST|', post, dim, 1.05)
            c[_hi('PIVOT_PRESENT:' + pivot, dim)] += 1.0
    z = math.sqrt(sum((v * v for v in c.values()))) or 1.0
    return {int(k): float(v) / z for k, v in c.items()}

